import { z } from 'zod'

const missingApiKey = 'Set CIRCLEBACK_API_KEY or pass apiKey.'
const apiKey = z.string().optional().pipe(z.string({ error: missingApiKey }).trim().min(1, missingApiKey))

export const circlebackConfigSchema = z.object({
  /** Stable account/installation namespace. Use a new sourceId when changing accounts or filters. */
  sourceId: z.string().refine((value) => value.trim() !== '', 'must not be blank'),
  /** Schema setup only; runtime pipeline factories do not change raw tables. */
  database: z.string(),
  ownership: z.enum(['All', 'Mine', 'Shared']),
  /** Circleback API key; read when a stream runs, never by schema commands. */
  apiKey,
})

export type CirclebackConfig = z.input<typeof circlebackConfigSchema>

export const circlebackReaderConfigSchema = circlebackConfigSchema.omit({ database: true })
export type CirclebackReaderConfig = z.input<typeof circlebackReaderConfigSchema>

// Collections are fully revisited on every run.
export const circlebackConfig: CirclebackConfig = {
  sourceId: 'circleback',
  database: 'default',
  ownership: 'All',
  apiKey: process.env.CIRCLEBACK_API_KEY,
}

import { HttpError, paginate, rawRows, type ErrorClassifier, type Page, type SourceContext } from '@chkit/plugin-ingest'
import { z } from 'zod'

import { circlebackReaderConfigSchema, type CirclebackReaderConfig } from './config.js'

export type CirclebackObject = Record<string, unknown>
export type CirclebackCollection = '/meetings' | '/action-items' | '/people' | '/companies'
export type CirclebackSettings = Omit<z.output<typeof circlebackReaderConfigSchema>, 'apiKey'>
export type TranscriptRead =
  | { status: 'available'; data: z.output<typeof transcriptSegments> }
  | { status: 'forbidden' | 'not_found'; data: null }

export interface CirclebackClient {
  settings: CirclebackSettings
  pages<T extends CirclebackObject>(path: CirclebackCollection, item: z.ZodType<T>, query?: Record<string, string>): AsyncGenerator<Page<T, string>>
  detail<T extends CirclebackObject>(path: string, item: z.ZodType<T>): Promise<T>
  transcript(meetingId: string): Promise<TranscriptRead>
}

export const circlebackId = z.int().positive()
export const nonBlankString = z.string().refine((value) => value.trim() !== '', 'must not be blank')
/** Tag names are the requested projection; provider objects otherwise stay intact. */
export const circlebackTags = z.array(z.looseObject({ name: nonBlankString })).transform((tags) => tags.map((tag) => tag.name)).optional()
const baseUrl = 'https://circleback.ai/api'
const transcriptSegments = z.array(z.looseObject({ speaker: z.string().nullable(), text: z.string(), timestamp: z.number() }))
const unavailable = new Map<number, 'forbidden' | 'not_found'>([[403, 'forbidden'], [404, 'not_found']])

export function createCirclebackClient(context: SourceContext, config: CirclebackReaderConfig): CirclebackClient {
  const { apiKey, ...settings } = circlebackReaderConfigSchema.parse(config)
  const get = (url: string) => context.fetch(url, { redirect: 'error', headers: { Authorization: `Bearer ${apiKey}`, Accept: 'application/json' } })
  return {
    settings,
    pages<T extends CirclebackObject>(path: CirclebackCollection, item: z.ZodType<T>, query: Record<string, string> = {}) {
      const initial = new URL(`${baseUrl}${path}`)
      for (const [key, value] of Object.entries(query)) initial.searchParams.set(key, value)
      const page = z.array(item)
      return paginate<T, string>({
        context, initial: initial.toString(), label: `GET ${path}`,
        fetchPage: async (url = initial.toString()) => {
          const response = await get(url)
          return { items: page.parse(await response.json()), next: nextLink(response.headers.get('link'), url, query) }
        },
      })
    },
    async detail<T extends CirclebackObject>(path: string, item: z.ZodType<T>) {
      const response = await get(`${baseUrl}${path}`)
      return item.parse(await response.json())
    },
    async transcript(meetingId: string) {
      let response: Response
      try {
        response = await get(`${baseUrl}/meeting/${encodeURIComponent(meetingId)}/transcript`)
      } catch (error) {
        const status = error instanceof HttpError ? unavailable.get(error.status) : undefined
        if (status) return { status, data: null }
        throw error
      }
      return { status: 'available', data: transcriptSegments.parse(await response.json()) }
    },
  }
}

export function classifyCirclebackError(cause: unknown): ReturnType<ErrorClassifier> {
  if (!(cause instanceof HttpError) || cause.status !== 429) return undefined
  const reset = cause.response.headers.get('ratelimit-reset')
  const resetMs = reset?.trim() ? Number(reset) * 1000 : Number.NaN
  return { kind: 'rate_limited', retryAfterMs: cause.retryAfterMs ?? (Number.isFinite(resetMs) && resetMs >= 0 ? resetMs : undefined) }
}

export function toCirclebackRows<T extends CirclebackObject>(items: readonly T[], id: (item: T) => string | number, sourceId: string) {
  return rawRows(items.map((data) => ({ source_id: sourceId, data })), (item) => JSON.stringify([sourceId, id(item.data)]))
}

function nextLink(header: string | null, current: string, query: Record<string, string>): string | undefined {
  if (!header?.trim()) return undefined
  const candidates: string[] = []
  for (const part of header.split(/,(?=\s*<)/)) {
    const link = /^\s*<([^>]+)>\s*(.*)$/.exec(part)
    if (!link) throw new Error('Circleback returned a malformed Link header.')
    const relation = /;\s*rel\s*=\s*(?:"([^"]+)"|([^;\s]+))/.exec(link[2] ?? '')
    if (!(relation?.[1] ?? relation?.[2])?.split(/\s+/).includes('next')) continue
    if (!link[1]) throw new Error('Circleback next page URL is missing.')
    candidates.push(link[1])
  }
  if (candidates.length > 1) throw new Error('Circleback returned multiple next pages.')
  const value = candidates[0]
  if (!value) return undefined
  if (!URL.canParse(value, current)) throw new Error('Circleback returned an invalid next page URL.')
  const next = new URL(value, current)
  if (next.origin !== 'https://circleback.ai' || next.pathname !== new URL(current).pathname || next.username || next.password || next.hash) {
    throw new Error('Circleback next page changed the collection or origin.')
  }
  for (const [key, value] of Object.entries(query)) {
    const values = next.searchParams.getAll(key)
    if (values.length > 1 || values.some((nextValue) => nextValue !== value)) {
      throw new Error(`Circleback next page changed the ${key} filter.`)
    }
    next.searchParams.set(key, value)
  }
  return next.toString()
}

import { rawTable, type SourceContext } from '@chkit/plugin-ingest'
import { z } from 'zod'

import { circlebackTags, createCirclebackClient, nonBlankString, toCirclebackRows } from '../client.js'
import { circlebackConfig, type CirclebackReaderConfig } from '../config.js'

const meeting = z.looseObject({ id: nonBlankString, tags: circlebackTags })

export const circleback_meetingsRaw = rawTable({ database: circlebackConfig.database, name: 'circleback_meetings_raw' })

export async function* readMeetings(context: SourceContext, config: CirclebackReaderConfig) {
  const client = createCirclebackClient(context, config)
  for await (const page of client.pages('/meetings', meeting, { ownership: client.settings.ownership })) {
    yield { rows: toCirclebackRows(page.items, (item) => item.id, client.settings.sourceId) }
  }
}

import { rawRows, rawTable, type SourceContext } from '@chkit/plugin-ingest'
import { z } from 'zod'

import { createCirclebackClient, nonBlankString, type CirclebackObject } from '../client.js'
import { circlebackConfig, type CirclebackReaderConfig } from '../config.js'

const meeting = z.looseObject({ id: nonBlankString })

export const circleback_meetingTranscriptsRaw = rawTable({ database: circlebackConfig.database, name: 'circleback_meeting_transcripts_raw' })

/** Discover every eligible meeting here: old meetings can gain transcripts without metadata changes. */
export async function* readMeetingTranscripts(context: SourceContext, config: CirclebackReaderConfig) {
  const client = createCirclebackClient(context, config)
  const { ownership, sourceId } = client.settings
  for await (const page of client.pages('/meetings', meeting, { ownership })) {
    for (const { id } of page.items) {
      const snapshot = await client.transcript(id)
      const observations: CirclebackObject[] = [{ source_id: sourceId, meeting_id: id, kind: 'availability', status: snapshot.status }]
      if (snapshot.status === 'available') observations.unshift({ source_id: sourceId, kind: 'transcript', meeting_id: id, ...snapshot })
      // Unavailability changes read evidence, not the last successful transcript snapshot.
      yield { rows: rawRows(observations, (item) => JSON.stringify(item.kind === 'transcript' ? [sourceId, id] : [sourceId, id, 'availability'])) }
    }
  }
}

import { rawTable, type SourceContext } from '@chkit/plugin-ingest'
import { z } from 'zod'

import { circlebackId, circlebackTags, createCirclebackClient, nonBlankString, toCirclebackRows } from '../client.js'
import { circlebackConfig, type CirclebackReaderConfig } from '../config.js'

// The official OpenAPI and Circleback CLI enumerate exactly these native completion statuses.
const statuses = ['PENDING', 'DONE']
const actionItem = z.looseObject({ id: circlebackId, meetingIds: z.array(nonBlankString), tags: circlebackTags })

export const circleback_actionItemsRaw = rawTable({ database: circlebackConfig.database, name: 'circleback_action_items_raw' })

export async function* readActionItems(context: SourceContext, config: CirclebackReaderConfig) {
  const client = createCirclebackClient(context, config)
  for (const status of statuses) {
    for await (const page of client.pages('/action-items', actionItem, { assigneeType: 'Anyone', status })) {
      if (page.items.some((item) => item.status !== status)) throw new Error(`Circleback returned an action item outside the ${status} status partition.`)
      yield { rows: toCirclebackRows(page.items, (item) => item.id, client.settings.sourceId) }
    }
  }
}

import { rawTable, type SourceContext } from '@chkit/plugin-ingest'
import { z } from 'zod'

import { circlebackId, circlebackTags, createCirclebackClient, toCirclebackRows } from '../client.js'
import { circlebackConfig, type CirclebackReaderConfig } from '../config.js'

const person = z.looseObject({ id: circlebackId, tags: circlebackTags })
const personDetail = person.extend({ externalLinks: z.array(z.unknown()) })

export const circleback_peopleRaw = rawTable({ database: circlebackConfig.database, name: 'circleback_people_raw' })

export async function* readPeople(context: SourceContext, config: CirclebackReaderConfig) {
  const client = createCirclebackClient(context, config)
  for await (const page of client.pages('/people', person)) {
    for (const listed of page.items) {
      const detail = await client.detail(`/person/${listed.id}`, personDetail)
      if (detail.id !== listed.id) throw new Error('Circleback person detail changed its ID.')
      yield { rows: toCirclebackRows([{ ...listed, ...detail }], (item) => item.id, client.settings.sourceId) }
    }
  }
}

import { rawRows, rawTable, type SourceContext } from '@chkit/plugin-ingest'
import { z } from 'zod'

import { circlebackId, circlebackTags, createCirclebackClient, nonBlankString } from '../client.js'
import { circlebackConfig, type CirclebackReaderConfig } from '../config.js'

const company = z.looseObject({ domain: nonBlankString, id: circlebackId.optional(), tags: circlebackTags })
const companyDetail = company.extend({
  people: z.array(z.looseObject({ id: circlebackId, companyId: circlebackId.nullable() })),
  externalLinks: z.array(z.unknown()),
})

export const circleback_companiesRaw = rawTable({ database: circlebackConfig.database, name: 'circleback_companies_raw' })

export async function* readCompanies(context: SourceContext, config: CirclebackReaderConfig) {
  const client = createCirclebackClient(context, config)
  const { sourceId } = client.settings
  for await (const page of client.pages('/companies', company)) {
    for (const listed of page.items) {
      const detail = await client.detail(`/company/${encodeURIComponent(listed.domain)}`, companyDetail)
      if (detail.domain !== listed.domain) throw new Error('Circleback company detail changed its domain.')
      const companyIds = new Set([listed.id, detail.id, ...detail.people.map((person) => person.companyId)].flatMap((id) => id ?? []))
      if (companyIds.size > 1) throw new Error('Circleback company returned conflicting numeric company IDs.')
      const snapshot = { source_id: sourceId, company_id: [...companyIds][0] ?? null, data: { ...listed, ...detail } }
      // The provider domain is always the identity, even when an optional numeric ID appears later.
      yield { rows: rawRows([snapshot], () => JSON.stringify([sourceId, listed.domain])) }
    }
  }
}

import { expect, test } from 'bun:test'
import { runIngestion, selectStreams } from '@chkit/plugin-ingest'
import { createMemoryDestination, createMemoryJournal } from '@chkit/plugin-ingest/testing'

import { createCirclebackPipeline, circlebackPipeline } from '../index.js'
import { circlebackConfig, type CirclebackReaderConfig } from '../config.js'

const cutoff = new Date('2026-01-02T00:00:00Z')
const fixtureConfig = { ...circlebackConfig, apiKey: 'fixture' }
const resources = ['meetings', 'meeting_transcripts', 'action_items', 'people', 'companies']
const meeting = { id: 'meeting-a', name: 'Old meeting', updatedAt: '2020-01-01T00:00:00Z', notes: 'Provider notes',
  tags: [{ id: 10, name: 'Customer' }, { id: 11, name: 'Follow up' }], attendees: [{ profileId: 1 }],
  actionItems: [{ id: 252, status: 'PENDING' }], custom: { retained: true } }
const transcript = [{ speaker: null, text: 'Full transcript\nwith another line', timestamp: 0.25, custom: true }]
const pending = { id: 252, title: 'Follow up', status: 'PENDING', completedAt: null, assignee: { profileId: 1 }, meetingIds: ['meeting-a'], custom: true }
const done = { id: 253, title: 'Completed work', status: 'DONE', completedAt: '2020-01-01T00:00:00Z', assignee: null, meetingIds: [], custom: true }
const person = { id: 1, companyId: 3, firstName: 'John', lastName: 'Appleseed', email: 'john@initech.com', companyName: 'Initech', title: 'Operations', custom: true }
const personDetail = { ...person, externalLinks: [{ type: 'linkedin', objectType: 'person', url: 'https://www.linkedin.com/in/john-appleseed' }] }
const company = { domain: 'initech.com', name: 'Initech', avatarUrl: null, custom: true }
const companyDetail = { ...company, people: [person], externalLinks: [{ type: 'website', objectType: 'company', url: 'https://initech.com' }] }

type Pipeline = ReturnType<typeof createCirclebackPipeline>
type Responder = (url: URL, init: RequestInit) => Response | Promise<Response>

test('Circleback publishes five raw resources with scoped native IDs and string tag names', async () => {
  const calls: URL[] = [], env = circlebackEnv((url, init) => { calls.push(url); return fixtureResponse(url, init) }), pipeline = fixturePipeline()
  expect(circlebackPipeline.streams).toHaveLength(5)
  expect(pipeline.streams.map((stream) => stream.id).sort()).toEqual(resources.map((resource) => `circleback.${resource}`).sort())
  const journal = createMemoryJournal(), destination = createMemoryDestination()
  const result = await runIngestion(request(pipeline), { ...env, journal, destination, now: () => cutoff })
  expect(result.ok, JSON.stringify(result)).toBe(true)
  const expected = {
    meetings: [{ id: rowId('meeting-a'), raw: envelope({ ...meeting, tags: ['Customer', 'Follow up'] }) }],
    meeting_transcripts: [
      { id: rowId('meeting-a'), raw: { source_id: 'circleback', kind: 'transcript', meeting_id: 'meeting-a', status: 'available', data: transcript } },
      { id: JSON.stringify(['circleback', 'meeting-a', 'availability']), raw: { source_id: 'circleback', meeting_id: 'meeting-a', kind: 'availability', status: 'available' } },
    ],
    action_items: [pending, done].map((data) => ({ id: rowId(data.id), raw: envelope(data) })),
    people: [{ id: rowId(person.id), raw: envelope(personDetail) }],
    companies: [{ id: rowId(company.domain), raw: { source_id: 'circleback', company_id: 3, data: companyDetail } }],
  }
  expect(destination.tables.size).toBe(5)
  for (const [resource, rows] of Object.entries(expected)) {
    expect(destination.tables.get(`default.circleback_${resource}_raw`)?.map(({ id, raw }) => ({ id, raw }))).toEqual(rows)
    expect((await journal.readCheckpoint(`circleback.${resource}`)).envelope).toBeUndefined()
    expect((await journal.readCheckpoint(`circleback.${resource}`)).lastSuccessSeq).toBeGreaterThan(0)
  }
  expect(calls.some((url) => url.pathname.includes('/calendar') || url.pathname.includes('/tags') || url.hostname !== 'circleback.ai')).toBe(false)
})

test('all resources run alone and reversing stream order preserves their raw observations', async () => {
  const pipeline = fixturePipeline(), combined = createMemoryDestination()
  expect((await runIngestion(request({ ...pipeline, streams: [...pipeline.streams].reverse() }),
    { ...circlebackEnv(), journal: createMemoryJournal(), destination: combined, now: () => cutoff })).ok).toBe(true)
  for (const resource of resources) {
    const calls: URL[] = [], destination = createMemoryDestination()
    const env = circlebackEnv((url, init) => { calls.push(url); return fixtureResponse(url, init) })
    const selected = request(pipeline, resource)
    expect(selected.selected.map((entry) => entry.stream.id)).toEqual([`circleback.${resource}`])
    expect((await runIngestion(selected, { ...env, journal: createMemoryJournal(), destination, now: () => cutoff })).ok).toBe(true)
    expect(destination.tables.size).toBe(1)
    expect(destination.tables.get(`default.circleback_${resource}_raw`)?.map(({ id, raw }) => ({ id, raw })))
      .toEqual(combined.tables.get(`default.circleback_${resource}_raw`)?.map(({ id, raw }) => ({ id, raw })))
    expect(calls).toHaveLength(resource === 'meetings' ? 1 : 2)
    if (resource === 'meetings') expect(calls.map((url) => url.pathname)).toEqual(['/api/meetings'])
    if (resource === 'action_items') expect(calls.every((url) => url.pathname === '/api/action-items')).toBe(true)
    if (resource === 'companies') expect(calls.map((url) => url.pathname)).toEqual(['/api/companies', '/api/company/initech.com'])
    if (resource === 'people') expect(calls.map((url) => url.pathname)).toEqual(['/api/people', '/api/person/1'])
  }
})

test('action items enumerate both native completion statuses for anyone and follow each partition to exhaustion', async () => {
  const calls: URL[] = []
  const env = circlebackEnv((url) => {
    calls.push(url)
    expect(url.searchParams.get('assigneeType')).toBe('Anyone')
    const status = url.searchParams.get('status')
    expect(status === 'PENDING' || status === 'DONE').toBe(true)
    const item = status === 'PENDING' ? pending : done
    if (url.searchParams.has('cursor')) return Response.json([{ ...item, id: item.id + 10 }])
    return Response.json([item], { headers: { Link: `</api/action-items?assigneeType=Anyone&status=${status}&cursor=next>; rel="next"` } })
  })
  const pipeline = fixturePipeline()
  const journal = createMemoryJournal(), destination = createMemoryDestination()
  expect((await runIngestion(request(pipeline, 'action_items'), { ...env, journal, destination, now: () => cutoff })).ok).toBe(true)
  expect(calls.map((url) => [url.searchParams.get('status'), url.searchParams.get('cursor')])).toEqual([
    ['PENDING', null], ['PENDING', 'next'], ['DONE', null], ['DONE', 'next'],
  ])
  expect(destination.tables.get('default.circleback_action_items_raw')?.map((row) => row.id)).toEqual([252, 262, 253, 263].map((id) => rowId(id)))
  expect((await journal.readCheckpoint('circleback.action_items')).lastSuccessSeq).toBeGreaterThan(0)
})

test('cursor-only continuations retain ownership and completion filters and conflicting links fail visibly', async () => {
  for (const resource of ['meetings', 'action_items']) {
    const calls: URL[] = []
    const env = circlebackEnv((url) => {
      calls.push(url)
      if (resource === 'action_items' && url.searchParams.get('status') === 'PENDING') return Response.json([])
      if (url.searchParams.has('cursor')) return Response.json(resource === 'meetings' ? [meeting] : [done])
      return Response.json([], { headers: { Link: `<${url.pathname}?cursor=next>; rel="next"` } })
    })
    const pipeline = fixturePipeline()
    expect((await runIngestion(request(pipeline, resource), { ...env, journal: createMemoryJournal(), destination: createMemoryDestination(), now: () => cutoff })).ok).toBe(true)
    const continued = calls.at(-1)
    expect(continued?.searchParams.get('cursor')).toBe('next')
    if (resource === 'meetings') expect(continued?.searchParams.get('ownership')).toBe('All')
    else {
      expect(continued?.searchParams.get('status')).toBe('DONE')
      expect(continued?.searchParams.get('assigneeType')).toBe('Anyone')
    }
  }
  for (const [resource, conflict] of [['meetings', 'ownership=Mine'], ['action_items', 'status=DONE'], ['action_items', 'assigneeType=Me']] satisfies [string, string][]) {
    let calls = 0
    const env = circlebackEnv((url) => {
      calls++
      return Response.json([], { headers: { Link: `<${url.pathname}?cursor=next&${conflict}>; rel="next"` } })
    })
    const pipeline = fixturePipeline()
    const journal = createMemoryJournal()
    expect((await runIngestion(request(pipeline, resource), { ...env, journal, destination: createMemoryDestination(), now: () => cutoff })).ok).toBe(false)
    expect(calls).toBe(1)
    expect((await journal.readCheckpoint(`circleback.${resource}`)).lastSuccessSeq).toBe(0)
  }
})

test('late transcripts on unchanged old meetings are revisited without running the meetings stream', async () => {
  let available = false
  const starts: string[] = [], calls: string[] = []
  const env = circlebackEnv((url) => {
    calls.push(url.pathname)
    if (url.pathname.endsWith('/transcript')) {
      if (!available) return new Response('unavailable', { status: url.pathname.includes('/meeting-a/') ? 403 : 404 })
      return Response.json(url.pathname.includes('/meeting-a/') ? transcript : [])
    }
    starts.push(url.search)
    return Response.json([meeting, { ...meeting, id: 'meeting-b' }])
  })
  const pipeline = fixturePipeline()
  const journal = createMemoryJournal(), destination = createMemoryDestination(), selected = request(pipeline, 'meeting_transcripts')
  expect((await runIngestion(selected, { ...env, journal, destination, now: () => cutoff })).ok).toBe(true)
  expect(destination.tables.get('default.circleback_meeting_transcripts_raw')?.map((row) => row.raw)).toEqual([
    { source_id: 'circleback', meeting_id: 'meeting-a', kind: 'availability', status: 'forbidden' },
    { source_id: 'circleback', meeting_id: 'meeting-b', kind: 'availability', status: 'not_found' },
  ])
  available = true
  expect((await runIngestion(selected, { ...env, journal, destination, now: () => new Date('2026-01-03') })).ok).toBe(true)
  expect(starts).toEqual(['?ownership=All', '?ownership=All'])
  expect(calls.filter((path) => path.endsWith('/transcript'))).toHaveLength(4)
  expect(destination.tables.get('default.circleback_meeting_transcripts_raw')?.slice(-4).map((row) => row.raw)).toEqual([
    { source_id: 'circleback', kind: 'transcript', meeting_id: 'meeting-a', status: 'available', data: transcript },
    { source_id: 'circleback', meeting_id: 'meeting-a', kind: 'availability', status: 'available' },
    { source_id: 'circleback', kind: 'transcript', meeting_id: 'meeting-b', status: 'available', data: [] },
    { source_id: 'circleback', meeting_id: 'meeting-b', kind: 'availability', status: 'available' },
  ])
  expect((await journal.readCheckpoint('circleback.meetings')).lastSuccessSeq).toBe(0)
  expect((await journal.readCheckpoint('circleback.meeting_transcripts')).envelope).toBeUndefined()
})

test('forbidden and not-found observations preserve prior transcript content while a successful empty transcript replaces it', async () => {
  let status = 200, empty = false
  const env = circlebackEnv((url) => url.pathname === '/api/meetings' ? Response.json([meeting])
    : status === 200 ? Response.json(empty ? [] : transcript) : new Response('unavailable', { status }))
  const pipeline = fixturePipeline()
  const journal = createMemoryJournal(), destination = createMemoryDestination(), selected = request(pipeline, 'meeting_transcripts')
  for (const nextStatus of [200, 403, 404, 200]) {
    status = nextStatus
    expect((await runIngestion(selected, { ...env, journal, destination, now: () => cutoff })).ok).toBe(true)
    const snapshots = destination.tables.get('default.circleback_meeting_transcripts_raw')?.filter((row) => row.id === rowId(meeting.id)) ?? []
    expect(snapshots.at(-1)?.raw).toMatchObject({ kind: 'transcript', status: 'available', data: empty ? [] : transcript })
    if (status === 404) empty = true
  }
  const rows = destination.tables.get('default.circleback_meeting_transcripts_raw') ?? []
  expect(rows.filter((row) => row.id === rowId(meeting.id))).toHaveLength(2)
  expect(rows.filter((row) => row.id !== rowId(meeting.id)).map((row) => row.raw)).toEqual(
    ['available', 'forbidden', 'not_found', 'available'].map((status) => ({ source_id: 'circleback', meeting_id: meeting.id, kind: 'availability', status })))
  expect(new Set(rows.map((row) => row.id)).size).toBe(2)
})

test('a transcript source failure leaves its full sync incomplete while all other resource streams succeed', async () => {
  let fail = true
  const transcriptCalls: string[] = []
  const env = circlebackEnv((url, init) => {
    if (url.pathname.endsWith('/transcript')) {
      transcriptCalls.push(url.pathname)
      if (fail) return new Response('unavailable', { status: 500 })
    }
    return fixtureResponse(url, init)
  })
  const pipeline = fixturePipeline()
  const journal = createMemoryJournal(), destination = createMemoryDestination()
  const failed = await runIngestion(request(pipeline), { ...env, journal, destination, now: () => cutoff })
  expect(failed.ok).toBe(false)
